IF NOT EXISTS(SELECT 1 FROM dbo.ImportOrderItems WHERE ImportOrderId=@import AND DataStatus=N'Orphan') THROW 59301,N'Orphan legacy không được giữ.',1;
IF (SELECT RecordOrigin FROM dbo.SalesOrders WHERE SalesOrderId=@sale)<>N'Sql' OR (SELECT RecordOrigin FROM dbo.SalesOrderItems WHERE SalesOrderId=@sale)<>N'Sql' THROW 59314,N'Bản ghi SQL mới không mặc định Sql.',1;
IF EXISTS(SELECT 1 FROM dbo.SalesOrderItems WHERE SalesOrderId=@sale AND ProductCode IS NOT NULL) THROW 59318,N'Snapshot SQL không giữ được ProductCode NULL.',1;
IF (SELECT Version FROM dbo.Products WHERE ProductId=@product)<>0 THROW 59302,N'Version 0 không hợp lệ.',1;
BEGIN TRY INSERT dbo.Products(ProductId,PublicId,Name) VALUES(NEWID(),'ABCDEFABCDEFABCDEFABCDEF',N'Sai'); THROW 59303,N'PublicId hoa không bị chặn.',1; END TRY BEGIN CATCH IF ERROR_NUMBER()=59303 THROW; END CATCH;
