BEGIN TRY INSERT dbo.ExportOrderItems(ExportOrderItemId,PublicId,ExportOrderId,LegacyProductObjectId,ExportedQuantity,AppliedQuantity,RecordOrigin,DataStatus) VALUES(NEWID(),'000000000000000000000022',@export,'ffffffffffffffffffffffff',1,2,N'Legacy',N'Orphan'); THROW 59305,N'Applied export vượt exported không bị chặn.',1; END TRY BEGIN CATCH IF ERROR_NUMBER()<>547 THROW; END CATCH;
BEGIN TRY INSERT dbo.ImportOrderItems(ImportOrderItemId,PublicId,ImportOrderId,ProductId,ProductVariantId,RecordOrigin,DataStatus) VALUES(NEWID(),'000000000000000000000036',@importSql,@product,@variant,N'Sql',N'Valid'); THROW 59319,N'Item Import SQL thiếu quantity không bị chặn.',1; END TRY BEGIN CATCH IF ERROR_NUMBER()<>547 THROW; END CATCH;
