BEGIN TRY INSERT dbo.StockOperations(StockOperationId,PublicId,IdempotencyKey,OperationType,ReversalOfOperationId,OccurredAtUtc,Version) VALUES(NEWID(),'000000000000000000000024',N'reversal-1',N'Reversal',@operation,SYSUTCDATETIME(),0); INSERT dbo.StockOperations(StockOperationId,PublicId,IdempotencyKey,OperationType,ReversalOfOperationId,OccurredAtUtc,Version) VALUES(NEWID(),'000000000000000000000025',N'reversal-2',N'Reversal',@operation,SYSUTCDATETIME(),0); THROW 59307,N'Hoàn tác lặp không bị chặn.',1; END TRY BEGIN CATCH IF ERROR_NUMBER()=59307 THROW; END CATCH;
BEGIN TRY INSERT dbo.StockOperations(StockOperationId,PublicId,IdempotencyKey,OperationType,ReversalOfOperationId,OccurredAtUtc,Version) VALUES(@selfOperation,'000000000000000000000026',N'self-reversal',N'Reversal',@selfOperation,SYSUTCDATETIME(),0); THROW 59308,N'Tự hoàn tác không bị chặn.',1; END TRY BEGIN CATCH IF ERROR_NUMBER()=59308 THROW; END CATCH;
BEGIN TRY INSERT dbo.StockMovementLines(StockMovementLineId,StockOperationId,ProductVariantId,QuantityForSaleChange,QuantityInStorageChange) VALUES(NEWID(),@operation,@variant,1,1); THROW 59309,N'Dòng stock trùng variant không bị chặn.',1; END TRY BEGIN CATCH IF ERROR_NUMBER()=59309 THROW; END CATCH;
INSERT dbo.StockOperations(StockOperationId,PublicId,IdempotencyKey,OperationType,OccurredAtUtc,Version) VALUES(@procedureSource,'000000000000000000000028',N'procedure-source',N'Adjustment',SYSUTCDATETIME(),0);
INSERT dbo.StockMovementLines(StockMovementLineId,StockOperationId,ProductVariantId,QuantityForSaleChange,QuantityInStorageChange,PurchaseCountChange) VALUES(NEWID(),@procedureSource,@variant,0.10,0.20,1),(NEWID(),@procedureSource,@variantTwo,0.30,0.40,2);
UPDATE dbo.Stocks SET QuantityForSale=QuantityForSale+CASE WHEN ProductVariantId=@variant THEN 0.10 ELSE 0.30 END, QuantityInStorage=QuantityInStorage+CASE WHEN ProductVariantId=@variant THEN 0.20 ELSE 0.40 END WHERE ProductVariantId IN(@variant,@variantTwo);
UPDATE dbo.Products SET PurchaseCount=PurchaseCount+CASE WHEN ProductId=@product THEN 1 ELSE 2 END WHERE ProductId IN(@product,@productTwo);
EXEC dbo.ReverseStockOperation @SourceOperationId=@procedureSource,@ReversalOperationId=@procedureReversal,@PublicId='000000000000000000000029',@IdempotencyKey=N'procedure-reversal',@OccurredAtUtc=@procedureOccurredAtUtc;
IF NOT EXISTS(SELECT 1 FROM dbo.StockOperations WHERE ReversalOfOperationId=@procedureSource) OR (SELECT COUNT(*) FROM dbo.StockMovementLines l JOIN dbo.StockOperations o ON o.StockOperationId=l.StockOperationId WHERE o.ReversalOfOperationId=@procedureSource)<>2 OR EXISTS(SELECT 1 FROM dbo.StockMovementLines l JOIN dbo.StockOperations o ON o.StockOperationId=l.StockOperationId WHERE o.ReversalOfOperationId=@procedureSource AND ((l.ProductVariantId=@variant AND (l.QuantityForSaleChange<>-0.10 OR l.QuantityInStorageChange<>-0.20 OR l.PurchaseCountChange<>-1)) OR (l.ProductVariantId=@variantTwo AND (l.QuantityForSaleChange<>-0.30 OR l.QuantityInStorageChange<>-0.40 OR l.PurchaseCountChange<>-2)) OR l.ProductVariantId NOT IN(@variant,@variantTwo))) THROW 59312,N'Procedure reversal không giữ đúng variant hoặc số lượng.',1;
IF EXISTS(SELECT 1 FROM dbo.Stocks WHERE (ProductVariantId=@variant AND (QuantityForSale<>1.25 OR QuantityInStorage<>2.75)) OR (ProductVariantId=@variantTwo AND (QuantityForSale<>3.25 OR QuantityInStorage<>4.75))) OR EXISTS(SELECT 1 FROM dbo.Products WHERE (ProductId=@product AND PurchaseCount<>1) OR (ProductId=@productTwo AND PurchaseCount<>2)) THROW 59313,N'Procedure reversal không khôi phục tồn kho hoặc lượt mua.',1;
INSERT dbo.FileLocations(FileLocationId,FileId,Provider,StorageNamespace,StorageKey,Status) VALUES(NEWID(),@file,N'Local',N'company-a/branch-a',N'catalog/ok-a.pdf',N'Pending'),(NEWID(),@file,N'Local',N'company-a/branch-a/catalog',N'catalog/ok-b.pdf',N'Pending');
DECLARE @badPath nvarchar(600);
DECLARE invalid_paths CURSOR LOCAL FAST_FORWARD FOR SELECT Value FROM (VALUES(N'.'),(N'..'),(N'a/./b'),(N'a/../b'),(N'a/ /b'),(N'a/b '),(N'a/b.'),(N'a/trailing. /b'),(N'CON'),(N'a/CON/b'),(N'C:/x'),(N'/x'),(N'a'+NCHAR(92)+N'b'),(N'a//b')) AS Invalid(Value);
OPEN invalid_paths; FETCH NEXT FROM invalid_paths INTO @badPath;
WHILE @@FETCH_STATUS=0
BEGIN
 BEGIN TRY INSERT dbo.FileLocations(FileLocationId,FileId,Provider,StorageNamespace,StorageKey,Status) VALUES(NEWID(),@file,N'Local',N'v1-test',@badPath,N'Pending'); THROW 59310,N'Path traversal không bị chặn.',1; END TRY BEGIN CATCH IF ERROR_NUMBER()<>547 THROW; END CATCH;
 FETCH NEXT FROM invalid_paths INTO @badPath;
END;
CLOSE invalid_paths; DEALLOCATE invalid_paths;
EXECUTE AS USER=N'OperationalRuntimeTest';
EXEC sys.sp_set_session_context @key=N'AllowAuditMaintenance',@value=1;
BEGIN TRY UPDATE dbo.ActivityLogs SET SafeDetail=N'Không được phép' WHERE 1=0; THROW 59315,N'Runtime vẫn sửa audit sau khi đặt session context.',1; END TRY BEGIN CATCH IF ERROR_NUMBER()<>229 THROW; END CATCH;
REVERT;
IF (SELECT COUNT(*) FROM dbo.MigrationMappings WHERE TargetTable=N'Products' AND TargetId=@product)<>2 THROW 59311,N'Không giữ được nhiều source map một target.',1;
ROLLBACK;
SELECT N'Operational constraint tests passed' AS Result;
GO
